        "params": {
          "id": "number"
        },
        "source": "esaggs",
      }
    },
    {
      "id": "col-1-b",
      "name": "Sum of bytes",
      "meta": {
        "type": "string",
        "field": "bytes",
        "index": "kibana_sample_data_logs",
        "params": {
