        },
        "source": "esaggs",
      }
    }
  ],
  "rows": [
    {
      "col-0-a": 0,
      "col-1-b": "23213FFF"
    }
  ]
}
```

If `id` argument is provided, look for a column with such an id and update its value.

Expression:
```
esaggs index={indexPatternLoad id="90943e30-9a47-11e8-b64d-95841ca0b247"} 
  aggs={aggHistogram id="a" enabled=true schema="segment" field="bytes" maxBars=34 interval="auto" has_extended_bounds=false min_doc_count=false}
  aggs={aggSum id="b" enabled=true schema="metric" field="bytes"} metricsAtAllLevels=false partialRows=false
| head 1
| staticColumn id="col-1-b" value="23213FFF"
```

Result of the `staticColumn` expression:
```JSON
{
  "type": "datatable",
  "columns": [
    {
      "id": "col-0-a",
      "name": "bytes",
      "meta": {
        "type": "number",
        "field": "bytes",
        "index": "kibana_sample_data_logs",
        "params": {
          "id": "number"
        },
        "source": "esaggs",
      }
    },
    {
      "id": "col-1-b",
      "name": "Sum of bytes",
      "meta": {
        "type": "string",
        "field": "bytes",
        "index": "kibana_sample_data_logs",
        "params": {
          "id": "string"
        },
        "source": "esaggs",
      }
    }
  ],
  "rows": [
